#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>

using namespace std;

const int MOD = 1000000007;

long long mod_pow(long long base, int exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

long long choose(int total, int take, const vector<long long>& factorial,
                 const vector<long long>& inverse_factorial) {
    return factorial[total] * inverse_factorial[take] % MOD *
           inverse_factorial[total - take] % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<pair<int, int>> blocked;
    blocked.reserve(m);
    for (int i = 0; i < m; ++i) {
        int y, x;
        cin >> y >> x;
        blocked.emplace_back(y, x);
    }

    sort(blocked.begin(), blocked.end());
    blocked.erase(unique(blocked.begin(), blocked.end()), blocked.end());

    const pair<int, int> start(0, 0);
    const pair<int, int> finish(n - 1, n - 1);
    if (binary_search(blocked.begin(), blocked.end(), start) ||
        binary_search(blocked.begin(), blocked.end(), finish)) {
        cout << 0 << '\n';
        return 0;
    }

    // Sparse obstacle counting scans obstacle pairs; use row-wise DP when
    // that pair work is no smaller than a full grid scan.
    if (blocked.size() < static_cast<size_t>(n)) {
        sort(blocked.begin(), blocked.end(), [](const pair<int, int>& a,
                                                const pair<int, int>& b) {
            const int sum_a = a.first + a.second;
            const int sum_b = b.first + b.second;
            if (sum_a != sum_b) return sum_a < sum_b;
            if (a.first != b.first) return a.first < b.first;
            return a.second < b.second;
        });

        const int max_steps = 2 * n - 2;
        vector<long long> factorial(max_steps + 1, 1);
        vector<long long> inverse_factorial(max_steps + 1, 1);
        for (int i = 1; i <= max_steps; ++i)
            factorial[i] = factorial[i - 1] * i % MOD;
        inverse_factorial[max_steps] = mod_pow(factorial[max_steps], MOD - 2);
        for (int i = max_steps; i > 0; --i)
            inverse_factorial[i - 1] = inverse_factorial[i] * i % MOD;

        vector<long long> ways(blocked.size(), 0);
        for (size_t i = 0; i < blocked.size(); ++i) {
            const int y = blocked[i].first;
            const int x = blocked[i].second;
            ways[i] = choose(y + x, y, factorial, inverse_factorial);
            for (size_t j = 0; j < i; ++j) {
                const int prev_y = blocked[j].first;
                const int prev_x = blocked[j].second;
                if (prev_y <= y && prev_x <= x) {
                    const int dy = y - prev_y;
                    const int dx = x - prev_x;
                    const long long paths_between = choose(
                        dy + dx, dy, factorial, inverse_factorial);
                    ways[i] = (ways[i] - ways[j] * paths_between % MOD + MOD) % MOD;
                }
            }
        }

        long long answer = choose(max_steps, n - 1, factorial, inverse_factorial);
        for (size_t i = 0; i < blocked.size(); ++i) {
            const int dy = n - 1 - blocked[i].first;
            const int dx = n - 1 - blocked[i].second;
            const long long paths_to_finish = choose(
                dy + dx, dy, factorial, inverse_factorial);
            answer = (answer - ways[i] * paths_to_finish % MOD + MOD) % MOD;
        }
        cout << answer << '\n';
        return 0;
    }

    // Contiguous one-dimensional DP fallback; the sorted obstacle list avoids
    // allocating a second N-by-N grid.
    vector<int> dp(n, 0);
    dp[0] = 1;
    size_t blocked_index = 0;
    for (int y = 0; y < n; ++y) {
        for (int x = 0; x < n; ++x) {
            const bool is_blocked =
                blocked_index < blocked.size() &&
                blocked[blocked_index].first == y &&
                blocked[blocked_index].second == x;
            if (is_blocked) ++blocked_index;

            if (is_blocked) {
                dp[x] = 0;
            } else if (x > 0) {
                dp[x] = (dp[x] + dp[x - 1]) % MOD;
            }
        }
    }

    cout << dp[n - 1] << '\n';
    return 0;
}
